Here are comprehensive unit tests for the `binary_search` function using `pytest`, covering happy path, edge cases, and error cases. The tests assume the input list is sorted (as required by the binary search algorithm).

```python
import pytest
from your_module import binary_search  # Replace with the actual module name


class TestBinarySearchHappyPath:
    """Tests for typical, expected usage."""

    def test_found_at_beginning(self):
        assert binary_search([1, 2, 3, 4, 5], 1) == 0

    def test_found_at_end(self):
        assert binary_search([1, 2, 3, 4, 5], 5) == 4

    def test_found_in_middle(self):
        assert binary_search([1, 2, 3, 4, 5], 3) == 2

    def test_large_array(self):
        arr = list(range(1000))
        assert binary_search(arr, 500) == 500

    def test_negative_numbers(self):
        assert binary_search([-5, -3, 0, 2, 4], -3) == 1

    def test_duplicate_elements(self):
        # Returns any valid index where the target occurs
        result = binary_search([1, 2, 2, 2, 3], 2)
        assert result in [1, 2, 3]

    def test_not_found(self):
        assert binary_search([1, 2, 3, 4, 5], 6) == -1


class TestBinarySearchEdgeCases:
    """Tests for boundary conditions."""

    def test_empty_list(self):
        assert binary_search([], 1) == -1

    def test_single_element_found(self):
        assert binary_search([5], 5) == 0

    def test_single_element_not_found(self):
        assert binary_search([5], 3) == -1

    def test_target_smaller_than_all(self):
        assert binary_search([10, 20, 30], 5) == -1

    def test_target_larger_than_all(self):
        assert binary_search([10, 20, 30], 35) == -1

    def test_large_values(self):
        assert binary_search([10**9, 10**9 + 1], 10**9) == 0

    def test_even_length_array(self):
        assert binary_search([1, 2, 3, 4], 3) == 2

    def test_odd_length_array(self):
        assert binary_search([1, 2, 3, 4, 5], 3) == 2


class TestBinarySearchErrorCases:
    """Tests for invalid or unexpected inputs that should raise errors."""

    def test_none_input(self):
        with pytest.raises(TypeError):
            binary_search(None, 1)

    def test_non_list_iterable_with_int_target(self):
        # String as array with int target -> TypeError during comparison
        with pytest.raises(TypeError):
            binary_search("abcde", 3)

    def test_non_comparable_target(self):
        arr = [1, 2, 3]
        with pytest.raises(TypeError):
            binary_search(arr, "a")

    def test_non_comparable_elements(self):
        arr = [1, "b", 3]
        # Will fail when trying to compare "b" < target
        with pytest.raises(TypeError):
            binary_search(arr, 2)
```

### Explanation of coverage

- **Happy path**: Normal sorted lists with target present at start, middle, end, large data, duplicates, and negative numbers. Also verifies `-1` when target is missing.
- **Edge cases**: Empty list, single-element list (found and not found), targets outside the range of all elements, even/odd length lists, and very large numbers.
- **Error cases**: Passing `None`, a non-list (string) with incompatible target type, a target of incompatible type, and a list containing elements that cannot be compared with the target — all expecting a `TypeError`.
